package app.loveu;
import android.content.Context;
import android.security.keystore.KeyGenParameterSpec;
import android.security.keystore.KeyProperties;
import android.util.AtomicFile;
import org.json.*;
import javax.crypto.*;
import javax.crypto.spec.GCMParameterSpec;
import java.security.KeyStore;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
public final class Vault {
 private final AtomicFile file;private static final String ALIAS="loveu.vault.v1";
 public Vault(Context context){file=new AtomicFile(new File(context.getFilesDir(),"vault.enc"));}
 private SecretKey key(boolean create) throws Exception {KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias(ALIAS)){if(!create)throw new IOException("Vault encryption key is unavailable");KeyGenerator gen=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");gen.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setRandomizedEncryptionRequired(true).build());gen.generateKey();}return (SecretKey)store.getKey(ALIAS,null);}
 public JSONObject read() throws Exception {synchronized(Vault.class){return readLocked();}}
 private JSONObject readLocked() throws Exception {
  byte[] data;try{data=file.readFully();}catch(FileNotFoundException missing){JSONObject root=new JSONObject();root.put("events",new JSONArray());root.put("settings",new JSONObject());root.put("timer",JSONObject.NULL);return root;}
  if(data.length<33||data[0]!=1)throw new IOException("Invalid encrypted vault");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(false),new GCMParameterSpec(128,Arrays.copyOfRange(data,1,13)));c.updateAAD(new byte[]{1});JSONObject root=new JSONObject(new String(c.doFinal(Arrays.copyOfRange(data,13,data.length)),StandardCharsets.UTF_8));validate(root);return root;
 }
 public void write(JSONObject root) throws Exception {synchronized(Vault.class){writeLocked(root);}}
 private void writeLocked(JSONObject root) throws Exception {validate(root);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key(true));c.updateAAD(new byte[]{1});byte[] encrypted=c.doFinal(root.toString().getBytes(StandardCharsets.UTF_8));FileOutputStream stream=null;try{stream=file.startWrite();stream.write(1);stream.write(c.getIV());stream.write(encrypted);file.finishWrite(stream);}catch(Exception e){if(stream!=null)file.failWrite(stream);throw e;}}
 private static void validate(JSONObject root) throws Exception {JSONArray events=root.getJSONArray("events");root.getJSONObject("settings");Object timer=root.get("timer");if(timer!=JSONObject.NULL&&!(timer instanceof JSONObject))throw new JSONException("Invalid timer");if(timer instanceof JSONObject){JSONObject draft=(JSONObject)timer;if(draft.has("state"))timerFromJson(draft.getJSONObject("state"));if(draft.has("needsReview")&&!(draft.get("needsReview") instanceof Boolean))throw new JSONException("Invalid review flag");}for(int i=0;i<events.length();i++)eventFromJson(events.getJSONObject(i));}
 public static JSONObject eventToJson(Domain.Event e) throws JSONException {Domain.validateEvent(e);JSONObject j=new JSONObject(e.extra);put(j,"id",e.id);put(j,"date",e.date);put(j,"time",e.time);put(j,"durationMillis",e.durationMillis);put(j,"place",e.place);put(j,"latitude",e.latitude);put(j,"longitude",e.longitude);put(j,"method",e.method);put(j,"partner",e.partner);put(j,"note",e.note);put(j,"source",e.source);put(j,"rating",e.rating);put(j,"protection",e.protection);put(j,"vocalLevel",e.vocalLevel);put(j,"outcomes",new JSONArray(e.outcomes));put(j,"positions",new JSONArray(e.positions));put(j,"partnerOrgasm",e.partnerOrgasm);put(j,"selfOrgasm",e.selfOrgasm);put(j,"partnerOrgasmCount",e.partnerOrgasmCount);put(j,"selfOrgasmCount",e.selfOrgasmCount);put(j,"selfCondition",conditionToJson(e.selfCondition));put(j,"partnerCondition",conditionToJson(e.partnerCondition));put(j,"detailsPending",e.detailsPending);put(j,"locationAccuracy",e.locationAccuracy);put(j,"locationCapturedAt",e.locationCapturedAt);return j;}
 private static JSONObject conditionToJson(Domain.Condition c)throws JSONException{JSONObject j=new JSONObject(c.extra);put(j,"energy",c.energy);put(j,"fatigue",c.fatigue);put(j,"mood",c.mood);put(j,"comfort",c.comfort);put(j,"tags",new JSONArray(c.tags));return j;}
 private static void put(JSONObject j,String k,Object v)throws JSONException{j.put(k,v==null?JSONObject.NULL:v);}
 private static String str(JSONObject j,String k)throws JSONException{if(j.isNull(k))return null;Object v=j.get(k);if(!(v instanceof String))throw new JSONException("Invalid string "+k);return (String)v;}
 private static Boolean bool(JSONObject j,String k)throws JSONException{if(j.isNull(k))return null;Object v=j.get(k);if(!(v instanceof Boolean))throw new JSONException("Invalid boolean "+k);return (Boolean)v;}
 private static Integer intOrNull(JSONObject j,String k)throws JSONException{if(j.isNull(k))return null;long n=integer(j,k);if(n<0||n>Integer.MAX_VALUE)throw new JSONException("Invalid integer "+k);return (int)n;}
 private static List<String> list(JSONObject j,String k)throws JSONException{List<String> out=new ArrayList<>();if(j.isNull(k))return out;Object value=j.get(k);if(!(value instanceof JSONArray))throw new JSONException("Invalid list "+k);JSONArray a=(JSONArray)value;for(int i=0;i<a.length();i++){Object v=a.get(i);if(!(v instanceof String))throw new JSONException("Invalid list item");out.add((String)v);}return out;}
 private static Map<String,Object> extras(JSONObject j,String... fields)throws JSONException{Set<String> names=new HashSet<>(Arrays.asList(fields));Map<String,Object> m=new LinkedHashMap<>();Iterator<String> it=j.keys();while(it.hasNext()){String k=it.next();if(!names.contains(k))m.put(k,j.get(k));}return m;}
 private static Domain.Condition condition(JSONObject j,String k)throws JSONException{Domain.Condition c=new Domain.Condition();if(j.isNull(k))return c;Object value=j.get(k);if(!(value instanceof JSONObject))throw new JSONException("Invalid condition");JSONObject v=(JSONObject)value;c.energy=intOrNull(v,"energy");c.fatigue=intOrNull(v,"fatigue");c.mood=intOrNull(v,"mood");c.comfort=intOrNull(v,"comfort");c.tags=list(v,"tags");c.extra=extras(v,"energy","fatigue","mood","comfort","tags");return c;}
 public static Domain.Event eventFromJson(JSONObject j)throws JSONException {Domain.Event e=new Domain.Event();e.id=str(j,"id");e.date=str(j,"date");e.time=str(j,"time");e.durationMillis=j.isNull("durationMillis")?null:integer(j,"durationMillis");e.place=str(j,"place");e.latitude=j.isNull("latitude")?null:coord(j,"latitude",90);e.longitude=j.isNull("longitude")?null:coord(j,"longitude",180);e.method=str(j,"method");e.partner=str(j,"partner");e.note=str(j,"note");e.source=str(j,"source");e.rating=intOrNull(j,"rating");e.protection=str(j,"protection");e.vocalLevel=str(j,"vocalLevel");e.outcomes=list(j,"outcomes");e.positions=list(j,"positions");e.partnerOrgasm=bool(j,"partnerOrgasm");e.selfOrgasm=bool(j,"selfOrgasm");e.partnerOrgasmCount=intOrNull(j,"partnerOrgasmCount");e.selfOrgasmCount=intOrNull(j,"selfOrgasmCount");e.selfCondition=condition(j,"selfCondition");e.partnerCondition=condition(j,"partnerCondition");e.detailsPending=Boolean.TRUE.equals(bool(j,"detailsPending"));e.locationAccuracy=j.isNull("locationAccuracy")?null:coord(j,"locationAccuracy",Integer.MAX_VALUE);e.locationCapturedAt=j.isNull("locationCapturedAt")?null:integer(j,"locationCapturedAt");e.extra=extras(j,"id","date","time","durationMillis","place","latitude","longitude","method","partner","note","source","rating","protection","vocalLevel","outcomes","positions","partnerOrgasm","selfOrgasm","partnerOrgasmCount","selfOrgasmCount","selfCondition","partnerCondition","detailsPending","locationAccuracy","locationCapturedAt");try{Domain.validateEvent(e);}catch(IllegalArgumentException bad){throw new JSONException(bad.getMessage());}return e;}
 private static long integer(JSONObject j,String k)throws JSONException{Object v=j.get(k);if(!(v instanceof Integer)&&!(v instanceof Long))throw new JSONException("Invalid integer "+k);return ((Number)v).longValue();}
 private static double coord(JSONObject j,String k,int max)throws JSONException{Object v=j.get(k);if(!(v instanceof Number))throw new JSONException("Invalid coordinate");double d=((Number)v).doubleValue();if(!Double.isFinite(d)||Math.abs(d)>max)throw new JSONException("Invalid coordinate");return d;}
 public static JSONObject timerToJson(Domain.Timer t){return new JSONObject(t.toMap());}
 public static Domain.Timer timerFromJson(JSONObject j)throws JSONException {Map<String,Object> m=new HashMap<>();for(String k:new String[]{"startWall","startElapsed","accumulated","lastResume","paused","bootCount"})m.put(k,j.get(k));return Domain.Timer.fromMap(m);}
}


